        "runtime" { Invoke-WinToolDriverRuntimeClick }
        "incompatible" { Invoke-WinToolDriverIncompatibleClick }
        default { Write-WinToolLog -Message (Get-WinToolText "drivers.tool.unknown" $Action) -Level "warn" }
    }
}

